raw_chrome.util_css:
@keyframes sway { 
  0%, 100% { transform: rotate(-1.5deg) translateX(-3px) translateY(1px); }
  50% { transform: rotate(1.5deg) translateX(3px) translateY(-1px); }
}
@keyframes ambient-pulse { 
  0%, 100% { opacity: 0.6; transform: scale(1); filter: blur(80px) saturate(120%); }
  50% { opacity: 0.9; transform: scale(1.05); filter: blur(100px) saturate(160%); }
}
@keyframes bloom-anim { 
  0% { opacity: 0; transform: scale(0.85) translateY(60px); filter: blur(24px); }
  100% { opacity: 1; transform: scale(1) translateY(0px); filter: blur(0px); }
}
.sway-text{display: inline-block; animation: 8s ease-in-out 0s infinite normal none running sway; transform-origin: center center; will-change: transform;}
.botanical-kerning{letter-spacing: -0.04em;}
.liquid-terminals{font-feature-settings: "swsh", "liga";}
.dew-btn{background: var(--color-glass); box-shadow: rgba(255, 255, 255, 0.2) 0px 1px 1px inset, rgba(255, 255, 255, 0.05) 0px -1px 4px inset, rgba(0, 0, 0, 0.3) 0px 10px 20px; backdrop-filter: blur(24px); border-radius: 9999px; transition: 0.5s cubic-bezier(0.16, 1, 0.3, 1); position: relative; overflow: hidden;}
.dew-btn::after{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle at center top, rgba(255, 255, 255, 0.15) 0%, transparent 60%); opacity: 0; transition: opacity 0.5s;}
.dew-btn:hover{box-shadow: rgba(255, 255, 255, 0.3) 0px 2px 4px inset, rgba(255, 255, 255, 0.1) 0px -2px 8px inset, rgba(0, 0, 0, 0.4) 0px 15px 30px, oklch(0.7 0.15 45 / 0.3) 0px 0px 30px; transform: translateY(-2px) scale(1.01);}
.dew-btn:hover::after{opacity: 1;}
.portal-mask{mask-image: radial-gradient(circle, black 35%, transparent 75%); will-change: transform;}
.bento-card{background: linear-gradient(160deg, oklch(1 0 0 / 0.06), oklch(1 0 0 / 0.01)); box-shadow: rgba(255, 255, 255, 0.01) 0px 0px 40px inset, rgba(0, 0, 0, 0.2) 0px 20px 50px; backdrop-filter: blur(40px); mask-image: linear-gradient(135deg, black 60%, transparent 100%); position: relative; transition: transform 0.6s cubic-bezier(0.16, 1, 0.3, 1); overflow: hidden;}
.bento-card::before{content: ""; position: absolute; inset: -200px; background: radial-gradient(circle 300px at var(--mouse-x, 50%) var(--mouse-y, 50%), oklch(70% 0.15 45 / 0.15), transparent 50%); pointer-events: none; mix-blend-mode: screen; z-index: 10; transition: opacity 0.4s; opacity: 0;}
.bento-card:hover::before{opacity: 1;}
.bento-card:hover{transform: translateY(-4px); mask-image: linear-gradient(135deg, black 70%, rgba(0, 0, 0, 0.3) 100%);}
.rhizome-bg{background-image: radial-gradient(oklch(1 0 0 / 0.03) 1px, transparent 1px); background-size: 40px 40px; mask-image: radial-gradient(at left center, black 20%, transparent 70%);}
.kinetic-z{will-change: transform; transform-style: preserve-3d;}
@keyframes pulse { 
  50% { opacity: 0.5; }
}
